        return if x < 0.0 { "-inf" } else { "inf" }.to_string();
    }

    // 6 significant digits in scientific form: "d.ddddde<exp>" or "-d.ddddde<exp>".
    let sci = format!("{:.5e}", x);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();

    if exp < -4 || exp >= 6 {
        let mantissa = strip_trailing_zeros(&sci[..epos]);
        format!(
            "{}e{}{:02}",
            mantissa,
            if exp < 0 { '-' } else { '+' },
            exp.abs()
        )
    } else {
        // %f with precision = 5 - exp, then strip trailing zeros.
        let prec = (5 - exp) as usize;
        let fixed = format!("{:.*}", prec, x);
        strip_trailing_zeros(&fixed)
    }
}

fn strip_trailing_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        t.trim_end_matches('.').to_string()
    } else {
        s.to_string()
    }
}

args.content:
//! Reimplementation of C++ std::stof (glibc strtof underneath):
//! - leading C whitespace skipped;
//! - optional '+'/'-' sign;
//! - "inf"/"infinity" and "nan" (case-insensitive);
//! - hexadecimal floats "0x1.8p1" (the 'p' exponent is optional for strtof);
//! - decimal floats with optional exponent; only the longest valid prefix is
//!   consumed ("0.5abc" -> 0.5, "1e" -> 1);
//! - no conversion possible -> std::invalid_argument -> terminate (SIGABRT);
//! - overflow or underflow (subnormal/zero result from a nonzero value)
//!   -> std::out_of_range -> terminate (SIGABRT).

pub enum StofError {
    Invalid,
    OutOfRange,
}

fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

fn is_hex_digit(b: u8) -> bool {
    b.is_ascii_hexdigit()
}

fn hex_val(b: u8) -> u32 {
    (b as char).to_digit(16).unwrap()
}

fn starts_with_ci(bytes: &[u8], pat: &[u8]) -> bool {
    bytes.len() >= pat.len()
        && bytes
            .iter()
            .zip(pat.iter())
            .all(|(a, b)| a.to_ascii_lowercase() == *b)
}

pub fn stof(s: &str) -> Result<f32, StofError> {
    let b = s.as_bytes();
    let mut i = 0usize;
    while i < b.len() && is_space(b[i]) {
        i += 1;
    }
    let sign_start = i;
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let rest = &b[i..];

    // inf / infinity
    if starts_with_ci(rest, b"infinity") || starts_with_ci(rest, b"inf") {
        return Ok(if neg {
            f32::NEG_INFINITY
        } else {
            f32::INFINITY
        });
    }
    // nan
    if starts_with_ci(rest, b"nan") {
        let v = f32::NAN;
        return Ok(if neg { -v } else { v });
    }

    // hexadecimal float: 0x<hex>[.<hex>][p[+-]dec]
    if rest.len() >= 2
        && rest[0] == b'0'
        && (rest[1] | 0x20) == b'x'
        && (rest.len() >= 3 && (is_hex_digit(rest[2])
            || (rest[2] == b'.' && rest.len() >= 4 && is_hex_digit(rest[3]))))
    {
        let mut j = 2usize;
        let mut mant: f64 = 0.0;
        let mut int_digits = 0u32; // integer hex digits folded into mantissa
        let mut extra_int = 0i32; // integer hex digits beyond mantissa capacity
        while j < rest.len() && is_hex_digit(rest[j]) {
            if int_digits < 13 {
                mant = mant * 16.0 + hex_val(rest[j]) as f64;
                int_digits += 1;
            } else {
                extra_int += 1;
            }
            j += 1;
        }
        let mut frac_digits = 0i32;
        if j < rest.len() && rest[j] == b'.' {
            j += 1;
            while j < rest.len() && is_hex_digit(rest[j]) {
                if int_digits < 13 {
                    mant = mant * 16.0 + hex_val(rest[j]) as f64;
                    int_digits += 1;
                }
                frac_digits += 1;
                j += 1;
            }
        }
        let mut pexp: i64 = 0;
        if j < rest.len() && (rest[j] | 0x20) == b'p' {
            let mut k = j + 1;
            let mut pneg = false;
            if k < rest.len() && (rest[k] == b'+' || rest[k] == b'-') {
                pneg = rest[k] == b'-';
                k += 1;
            }
            let dstart = k;
            let mut val: i64 = 0;
            while k < rest.len() && rest[k].is_ascii_digit() {
                val = (val * 10 + (rest[k] - b'0') as i64).min(100_000);
                k += 1;
            }
            if k > dstart {
                pexp = if pneg { -val } else { val };
            }
        }
        let exp2 = pexp + 4 * (extra_int as i64 - frac_digits as i64);
        let v = mant * 2f64.powi(exp2.clamp(-4000, 4000) as i32);
        let v = if neg { -v } else { v };
        return range_check(v, v != 0.0);
    }

    // decimal float: digits[.digits][e[+-]digits] or .digits[e...]
    let mut j = 0usize;
    let mut int_digits = 0usize;
    while j < rest.len() && rest[j].is_ascii_digit() {
        j += 1;
        int_digits += 1;
    }
    let mut frac_digits = 0usize;
    let mut frac_end = j;
    if j < rest.len() && rest[j] == b'.' {
        let mut k = j + 1;
        while k < rest.len() && rest[k].is_ascii_digit() {
            k += 1;
            frac_digits += 1;
        }
        if int_digits > 0 || frac_digits > 0 {
            frac_end = k;
        }
    }
    if int_digits == 0 && frac_digits == 0 {
        return Err(StofError::Invalid);
    }
    let mut end = frac_end;
    // optional exponent (back up if it has no digits)
    if end < rest.len() && (rest[end] | 0x20) == b'e' {
        let mut k = end + 1;
        if k < rest.len() && (rest[k] == b'+' || rest[k] == b'-') {
            k += 1;
        }
        let dstart = k;
        while k < rest.len() && rest[k].is_ascii_digit() {
            k += 1;
        }
        if k > dstart {
            end = k;
        }
    }

    let prefix = &s[sign_start..i + end];
    // Rust's f32 parser is correctly rounded, like strtof.
    let parse_target = prefix.strip_suffix('.').unwrap_or(prefix);
    let v: f32 = parse_target.parse().map_err(|_| StofError::Invalid)?;

    // Detect nonzero mantissa (for underflow detection without double parse).
    let nonzero = prefix
        .bytes()
        .take_while(|c| *c != b'e' && *c != b'E')
        .any(|c| (b'1'..=b'9').contains(&c));
    range_check(v as f64, nonzero)
}

/// glibc strtof sets ERANGE on overflow (result inf from finite input) and on
/// underflow (rounded result zero or subnormal while the value is nonzero);
/// std::stof then throws std::out_of_range.
fn range_check(v64: f64, nonzero: bool) -> Result<f32, StofError> {
    let v = v64 as f32;
    if v.is_infinite() {
        return Err(StofError::OutOfRange);
    }
    let a = v.abs();
    if nonzero && (a == 0.0 || a < f32::MIN_POSITIVE) {
        return Err(StofError::OutOfRange);
    }
    Ok(v)
}

/// Parse like std::stof; on failure mimic the C++ program: an uncaught
/// exception aborts the process (SIGABRT, exit code 134).
pub fn stof_or_abort(s: &str) -> f32 {
    match stof(s) {
        Ok(v) => v,
        Err(StofError::Invalid) => abort_like("std::invalid_argument"),
        Err(StofError::OutOfRange) => abort_like("std::out_of_range"),
    }
}

fn abort_like(exc: &str) -> ! {
    eprintln!("terminate called after throwing an instance of '{}'", exc);
    eprintln!("  what():  stof");
    std::process::abort();
}

