args.command:
cat > /tmp/fuzz.sh <<'EOF'
#!/bin/bash
E=/workspace/dataset/test20_executable
R=/output/target/release/test20
SEED=${1:-42}
N=${2:-400}
mism=0
for ((t=0; t<N; t++)); do
  # generate args with awk RNG
  args=$(awk -v seed=$((SEED*100000+t)) 'BEGIN{
    srand(seed);
    nchoices[0]=0; nchoices[1]=0; nchoices[2]=3; nchoices[3]=3; nchoices[4]=6; nchoices[5]=9;
    n = nchoices[int(rand()*6)];
    out="";
    specials[0]="0"; specials[1]="1"; specials[2]="-0"; specials[3]="0.0"; specials[4]="1.0"; specials[5]="2"; specials[6]="-1";
    bounds[0]="0.5"; bounds[1]="0.25"; bounds[2]="0.333333"; bounds[3]="0.666667"; bounds[4]="0.75"; bounds[5]="1.5"; bounds[6]="-0.5"; bounds[7]="1.2"; bounds[8]="0.8";
    precs[0]=1; precs[1]=2; precs[2]=3; precs[3]=6; precs[4]=9;
    for(i=0;i<n;i++){
      c=rand();
      if(c<0.15){ v=specials[int(rand()*7)]; }
      else if(c<0.25){ v=bounds[int(rand()*9)]; }
      else { p=precs[int(rand()*5)]; v=sprintf("%.*f", p, -1+rand()*3); }
      out = out (i?" ":"") v;
    }
    print out;
  }')
  $E $args > /tmp/fz_cpp.out 2>/dev/null; rc1=$?
  $R $args > /tmp/fz_rs.out 2>/dev/null; rc2=$?
  if ! cmp -s /tmp/fz_cpp.out /tmp/fz_rs.out || [ $rc1 -ne $rc2 ]; then
    mism=$((mism+1))
    echo "MISMATCH t=$t args=[$args] rc=$rc1/$rc2"
    diff <(tr " " "\n" < /tmp/fz_cpp.out) <(tr " " "\n" < /tmp/fz_rs.out) | head -6
    [ $mism -ge 8 ] && break
  fi
done
echo "done: $N cases, $mism mismatches"
EOF
chmod +x /tmp/fuzz.sh && /tmp/fuzz.sh 42 400

