args.command:
mkdir -p /tmp/scratch && cat > /tmp/scratch/t.rs <<'EOF'
fn hue_to_rgb(p: f32, q: f32, mut t: f32, variant: u8) -> f32 {
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    if t < 1.0 / 6.0 {
        return match variant {
            0 => p + (q - p) * 6.0 * t,
            1 => p + (q - p) * (6.0 * t),
            2 => p + (q - p) * t * 6.0,
            _ => p + t * (6.0 * (q - p)),
        };
    }
    if t < 1.0 / 2.0 { return q; }
    if t < 2.0 / 3.0 {
        return match variant {
            0 => p + (q - p) * (2.0 / 3.0 - t) * 6.0,
            1 => p + (q - p) * ((2.0 / 3.0 - t) * 6.0),
            _ => p + (q - p) * (2.0 / 3.0 - t) * 6.0,
        };
    }
    p
}
fn main() {
    // case t=1: color (0, -0.66, 2)
    let r: f32 = "0".parse().unwrap();
    let g: f32 = "-0.66".parse().unwrap();
    let b: f32 = "2".parse().unwrap();
    let min = g; let max = b;
    let l = (max + min) / 2.0;
    let d = max - min;
    let mut s = d / (2.0 - max - min);
    s = s * 1.5; if s < 0.0 { s = 0.0 } else if s > 1.0 { s = 1.0 }
    let h = ((r - g) / d + 4.0) * 60.0;
    println!("h={:?} s={:?} l={:?}", h, s, l);
    let hn = h / 360.0;
    let q = if l < 0.5 { l * (1.0 + s) } else { l + s - l * s };
    let p = 2.0 * l - q;
    println!("p={:?} q={:?}", p, q);
    for v in 0..4u8 {
        let rr = hue_to_rgb(p, q, hn + 1.0/3.0, v);
        println!("variant {} -> r={:?} g={:?} b={:?}", v, rr,
            hue_to_rgb(p, q, hn, v), hue_to_rgb(p, q, hn - 1.0/3.0, v));
    }
    // hue normalization probe: r=1,g=0.13,b=0 max==r g>b
    let x: f32 = 0.13; // parsed from "0.13"
    let x: f32 = "0.13".parse().unwrap();
    let d2: f32 = 1.0;
    let direct = (x / d2) * 60.0;
    let fmod_norm = ((6.0f32 + x / d2) % 6.0) * 60.0;
    let addsub = ((x / d2 + 6.0) - 6.0) * 60.0;
    let fmod2 = (((x / d2) % 6.0 + 6.0) % 6.0) * 60.0;
    println!("hue probe: direct={:?} fmod_norm={:?} addsub={:?} fmod2={:?}", direct, fmod_norm, addsub, fmod2);
