use std::fs;

fn fmt_g(v: f32) -> String {
    let x = v as f64;
    if x.is_nan() { return if x.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if x.is_infinite() { return if x < 0.0 { "-inf" } else { "inf" }.into() }
    let sci = format!("{:.5e}", x);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos+1..].parse().unwrap();
    if exp < -4 || exp >= 6 {
        let m = sci[..epos].to_string();
        let m = if m.contains('.') { m.trim_end_matches('0').trim_end_matches('.').to_string() } else { m };
        format!("{}e{}{:02}", m, if exp<0 {'-'} else {'+'}, exp.abs())
    } else {
        let s = format!("{:.*}", (5-exp) as usize, x);
        if s.contains('.') { s.trim_end_matches('0').trim_end_matches('.').to_string() } else { s }
    }
}

fn clamp01(v: f32) -> f32 { if v < 0.0 { 0.0 } else if 1.0 < v { 1.0 } else { v } }

fn h2r(p: f32, q: f32, mut t: f32, m1: u8, m3: u8) -> f32 {
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    if t < 1.0/6.0 {
        return match m1 {
            0 => p + (q-p)*6.0*t,
            1 => p + (q-p)*(6.0*t),
            2 => p + (q-p)*t*6.0,
            3 => p + t*(6.0*(q-p)),
            4 => p + t*((q-p)*6.0),
            _ => p + (6.0*(q-p))*t,
        };
    }
    if t < 1.0/2.0 { return q; }
    if t < 2.0/3.0 {
        return match m3 {
            0 => p + (q-p)*(2.0/3.0-t)*6.0,
            1 => p + (q-p)*((2.0/3.0-t)*6.0),
            _ => p + (2.0/3.0-t)*(6.0*(q-p)),
        };
    }
    p
}

fn saturated(r: f32, g: f32, b: f32, lv: u8, sv: u8, hv: u8, qv: u8, tv: u8, m1: u8, m3: u8) -> (f32,f32,f32) {
    let mut min = r; if g < min { min = g; } if b < min { min = b; }
    let mut max = r; if g > max { max = g; } if b > max { max = b; }
    let d = max - min;
    let l = match lv { 0 => (max+min)/2.0, 1 => min + d/2.0, _ => max - d/2.0 };
    let (h, mut s);
    if d == 0.0 { h = 0.0; s = 0.0; }
    else {
        s = match sv {
            0 => if l > 0.5 { d/(2.0-max-min) } else { d/(max+min) },
            1 => if l > 0.5 { d/(2.0-(max+min)) } else { d/(max+min) },
            _ => d/(1.0-(2.0*l-1.0).abs()),
        };
        h = if max == r {
            let x = (g-b)/d;
            match hv { 0 => (x + if g < b {6.0} else {0.0})*60.0, 1 => x*60.0 + if g < b {360.0} else {0.0}, _ => { let mut h = x*60.0; if h < 0.0 { h += 360.0; } h } }
        } else if max == g {
            let x = (b-r)/d;
            match hv { 0 => (x+2.0)*60.0, 1 => x*60.0+120.0, _ => x*60.0+120.0 }
        } else {
            let x = (r-g)/d;
            match hv { 0 => (x+4.0)*60.0, 1 => x*60.0+240.0, _ => x*60.0+240.0 }
        };
    }
    s = clamp01(s * 1.5);
    if s == 0.0 { return (l, l, l); }
    let hn = match tv { 0 => h/360.0, _ => h*(1.0/360.0) };
    let q = if l < 0.5 { l*(1.0+s) } else { match qv { 0 => l+s-l*s, _ => l+(s-l*s) } };
    let p = 2.0*l - q;
    (h2r(p,q,hn+1.0/3.0,m1,m3), h2r(p,q,hn,m1,m3), h2r(p,q,hn-1.0/3.0,m1,m3))
}

fn main() {
    let triples: Vec<Vec<f32>> = fs::read_to_string("/tmp/triples.txt").unwrap().lines()
        .map(|l| l.split_whitespace().map(|t| t.parse().unwrap()).collect()).collect();
    let expected: Vec<Vec<String>> = fs::read_to_string("/tmp/expected_sat.txt").unwrap().lines()
        .map(|l| l.split_whitespace().map(|t| t.to_string()).collect()).collect();
    let mut best = (usize::MAX, String::new());
    for lv in 0..3u8 { for sv in 0..3u8 { for hv in 0..3u8 { for qv in 0..2u8 { for tv in 0..2u8 { for m1 in 0..6u8 { for m3 in 0..3u8 {
        let mut mism = 0usize;
        for (i, t) in triples.iter().enumerate() {
            let (rr, gg, bb) = saturated(t[0], t[1], t[2], lv, sv, hv, qv, tv, m1, m3);
            let got = [fmt_g(rr), fmt_g(gg), fmt_g(bb)];
