fn fmt_g(v: f32) -> String {
    let x = v as f64;
    if x.is_nan() { return if x.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if x.is_infinite() { return if x < 0.0 { "-inf" } else { "inf" }.into() }
    let sci = format!("{:.5e}", x);
