        format!("{}e{}{:02}", m, if exp<0 {'-'} else {'+'}, exp.abs())
    } else {
        let s = format!("{:.*}", (5-exp) as usize, x);
        if s.contains('.') { s.trim_end_matches('0').trim_end_matches('.').to_string() } else { s }
    }
}

fn clamp01(v: f32) -> f32 { if v < 0.0 { 0.0 } else if 1.0 < v { 1.0 } else { v } }

fn h2r(p: f32, q: f32, mut t: f32, m1: u8, m3: u8) -> f32 {
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    if t < 1.0/6.0 {
        return match m1 {
            0 => p + (q-p)*6.0*t,
            1 => p + (q-p)*(6.0*t),
            2 => p + (q-p)*t*6.0,
            3 => p + t*(6.0*(q-p)),
            4 => p + t*((q-p)*6.0),
            _ => p + (6.0*(q-p))*t,
        };
    }
    if t < 1.0/2.0 { return q; }
    if t < 2.0/3.0 {
        return match m3 {
            0 => p + (q-p)*(2.0/3.0-t)*6.0,
            1 => p + (q-p)*((2.0/3.0-t)*6.0),
            _ => p + (2.0/3.0-t)*(6.0*(q-p)),
        };
    }
    p
}

fn saturated(r: f32, g: f32, b: f32, lv: u8, sv: u8, hv: u8, qv: u8, tv: u8, m1: u8, m3: u8) -> (f32,f32,f32) {
    let mut min = r; if g < min { min = g; } if b < min { min = b; }
    let mut max = r; if g > max { max = g; } if b > max { max = b; }
    let d = max - min;
    let l = match lv { 0 => (max+min)/2.0, 1 => min + d/2.0, _ => max - d/2.0 };
