            0 => if l > 0.5 { d/(2.0-max-min) } else { d/(max+min) },
            1 => if l > 0.5 { d/(2.0-(max+min)) } else { d/(max+min) },
            _ => d/(1.0-(2.0*l-1.0).abs()),
